static void process_files ( const char * fname , const char * dir , void * callback ( char * ) ) { assert ( fname ) ; assert ( dir ) ; assert ( callback ) ; process_file ( fname , dir , callback ) ; struct stat s ; int i ; for ( i = 1 ; i <= 5 ; i ++ ) { char * newname ; if ( asprintf ( & newname , "%s.%d" , fname , i ) == - 1 ) { errExit ( "asprintf" ) ; } if ( stat ( newname , & s ) == 0 ) { process_file ( newname , dir , callback ) ; } } } 